    private static void AssertBattlefieldFirstUnitMoveOtherResolved(
        ResolutionResult beforePlay,
        ResolutionResult result)
    {
        var battlefieldObjectId = BattlefieldObjectIdForCardNo(
            result.State,
            "P1",
            MeteorSpringBattlefieldFirstUnitMoveOtherCardNo);
        var triggerEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "BATTLEFIELD_TRIGGER_RESOLVED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldFirstUnitPlayedMoveOtherToBase, StringComparison.Ordinal));
        Assert.Equal("P1", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(MeteorSpringBattlefieldFirstUnitMoveOtherCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal($"BATTLEFIELD:{battlefieldObjectId}", triggerEvent.Payload["destination"]);

        var playedUnitObjectId = Assert.IsType<string>(triggerEvent.Payload["playedUnitObjectId"]);
        var movedUnitObjectId = Assert.IsType<string>(triggerEvent.Payload["targetObjectId"]);
        Assert.NotEqual(playedUnitObjectId, movedUnitObjectId);
        Assert.Contains(playedUnitObjectId, beforePlay.State.PlayerZones["P1"].Hand);
        Assert.Contains(movedUnitObjectId, beforePlay.State.PlayerZones["P1"].Battlefields);
        Assert.Equal(battlefieldObjectId, beforePlay.State.ObjectLocations[movedUnitObjectId].BattlefieldObjectId);

        var effectId = $"BATTLEFIELD_FIRST_UNIT_PLAYED_MOVE_OTHER_TO_BASE_USED:P1:{battlefieldObjectId}";
        Assert.Equal(effectId, triggerEvent.Payload["effectId"]);
        Assert.Contains(effectId, result.State.UntilEndOfTurnEffects);

        var moveEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "UNIT_MOVED_TO_BASE", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["reason"] as string, TriggerKinds.BattlefieldFirstUnitPlayedMoveOtherToBase, StringComparison.Ordinal));
        Assert.Equal("P1", moveEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, moveEvent.Payload["sourceObjectId"]);
        Assert.Equal(movedUnitObjectId, moveEvent.Payload["targetObjectId"]);
        Assert.Equal("BATTLEFIELD", moveEvent.Payload["originZone"]);
        Assert.Equal("BASE", moveEvent.Payload["destinationZone"]);

        Assert.Contains(playedUnitObjectId, result.State.PlayerZones["P1"].Battlefields);
        Assert.Contains(movedUnitObjectId, result.State.PlayerZones["P1"].Base);
        Assert.DoesNotContain(movedUnitObjectId, result.State.PlayerZones["P1"].Battlefields);
        var playedLocation = result.State.ObjectLocations[playedUnitObjectId];
        Assert.Equal("BATTLEFIELD", playedLocation.Zone);
        Assert.Equal(battlefieldObjectId, playedLocation.BattlefieldObjectId);
        var movedLocation = result.State.ObjectLocations[movedUnitObjectId];
        Assert.Equal("BASE", movedLocation.Zone);
        Assert.Null(movedLocation.BattlefieldObjectId);
        AssertNoHiddenZoneLeak(result);
    }

    private static void AssertBattlefieldUnitReturnedCallRuneResolved(
        ResolutionResult beforeSpell,
        ResolutionResult result)
    {
        var battlefieldObjectId = BattlefieldObjectIdForCardNo(
            result.State,
            "P1",
            GhostBayBattlefieldUnitReturnedCallRuneCardNo);
        var returnedObjectId = FindBattlefieldUnitByCardNo(
            beforeSpell.State,
            "P1",
            WatchfulSentinelCardNo,
            battlefieldObjectId)
            ?? throw new InvalidOperationException("B0 Ghost Bay assertion could not locate Watchful Sentinel at Ghost Bay.");
        var reconsiderObjectId = FindHandCardObjectByCardNo(
            beforeSpell.State,
            "P1",
            ReconsiderSpellCardNo)
            ?? throw new InvalidOperationException("B0 Ghost Bay assertion could not locate Reconsider in P1 hand.");
        var expectedSpellRuneObjectId = beforeSpell.State.PlayerZones["P1"].RuneDeck.ElementAtOrDefault(0)
            ?? throw new InvalidOperationException("B0 Ghost Bay assertion expected at least one rune for Reconsider.");
        var expectedGhostBayRuneObjectId = beforeSpell.State.PlayerZones["P1"].RuneDeck.ElementAtOrDefault(1)
            ?? throw new InvalidOperationException("B0 Ghost Bay assertion expected a second rune for Ghost Bay.");

        var returnedEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "UNIT_RETURNED_TO_HAND", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["targetObjectId"] as string, returnedObjectId, StringComparison.Ordinal));
        Assert.Equal(reconsiderObjectId, returnedEvent.Payload["sourceObjectId"]);
        Assert.Equal("P1", returnedEvent.Payload["ownerPlayerId"]);

        var triggerEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "BATTLEFIELD_TRIGGER_RESOLVED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldUnitReturnedPayCallRune, StringComparison.Ordinal));
        Assert.Equal("P1", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(GhostBayBattlefieldUnitReturnedCallRuneCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal(reconsiderObjectId, triggerEvent.Payload["sourceObjectId"]);
        Assert.Equal(returnedObjectId, triggerEvent.Payload["returnedObjectId"]);

        var costPaid = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "COST_PAID", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["reason"] as string, TriggerKinds.BattlefieldUnitReturnedPayCallRune, StringComparison.Ordinal));
        Assert.Equal("P1", costPaid.Payload["playerId"]);
        Assert.Equal(1, costPaid.Payload["mana"]);
        Assert.Equal(beforeSpell.State.RunePools["P1"].Mana - 2, result.State.RunePools["P1"].Mana);

        Assert.Equal(2, result.Events.Count(gameEvent => string.Equals(gameEvent.Kind, "RUNES_CALLED", StringComparison.Ordinal)));
        var reconsiderRuneEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "RUNES_CALLED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["sourceObjectId"] as string, reconsiderObjectId, StringComparison.Ordinal));
        Assert.Equal([expectedSpellRuneObjectId], Assert.IsType<string[]>(reconsiderRuneEvent.Payload["runeObjectIds"]));
        var ghostBayRuneEvent = Assert.Single(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "RUNES_CALLED", StringComparison.Ordinal)
            && gameEvent.Payload.TryGetValue("reason", out var reason)
            && string.Equals(reason as string, TriggerKinds.BattlefieldUnitReturnedPayCallRune, StringComparison.Ordinal));
        Assert.Equal(battlefieldObjectId, ghostBayRuneEvent.Payload["sourceObjectId"]);
        Assert.Equal([expectedGhostBayRuneObjectId], Assert.IsType<string[]>(ghostBayRuneEvent.Payload["runeObjectIds"]));
        Assert.Equal(returnedObjectId, ghostBayRuneEvent.Payload["returnedObjectId"]);

        Assert.Contains(returnedObjectId, result.State.PlayerZones["P1"].Hand);
        Assert.DoesNotContain(returnedObjectId, result.State.PlayerZones["P1"].Battlefields);
        Assert.Contains(expectedSpellRuneObjectId, result.State.PlayerZones["P1"].Base);
        Assert.Contains(expectedGhostBayRuneObjectId, result.State.PlayerZones["P1"].Base);
        Assert.DoesNotContain(expectedSpellRuneObjectId, result.State.PlayerZones["P1"].RuneDeck);
        Assert.DoesNotContain(expectedGhostBayRuneObjectId, result.State.PlayerZones["P1"].RuneDeck);
        AssertNoHiddenZoneLeak(result);
    }

    private static void AssertBattlefieldHeldDrawResolved(
        ResolutionResult beforeBattle,
        ResolutionResult result)
    {
        var battlefieldObjectId = BattlefieldObjectIdForCardNo(
            result.State,
            "P2",
            HiddenValleyBattlefieldHeldDrawCardNo);
        var attackerObjectId = FindBattlefieldUnitByCardNo(
            beforeBattle.State,
            "P1",
            WatchfulSentinelCardNo,
            battlefieldObjectId)
            ?? throw new InvalidOperationException("B0 Hidden Valley assertion could not locate the attacking Watchful Sentinel.");
        var defenderObjectId = FindBattlefieldUnitByCardNo(
            beforeBattle.State,
            "P2",
            WildclawBeastmasterCardNo,
            battlefieldObjectId)
            ?? throw new InvalidOperationException("B0 Hidden Valley assertion could not locate the defending Wildclaw Beastmaster.");
        var expectedDrawnObjectId = beforeBattle.State.PlayerZones["P2"].MainDeck.FirstOrDefault()
            ?? throw new InvalidOperationException("B0 Hidden Valley assertion expected at least one P2 main-deck card to draw.");

        var resultEvents = result.Events.ToArray();
        var heldIndex = Array.FindIndex(resultEvents, gameEvent => string.Equals(gameEvent.Kind, "BATTLEFIELD_HELD", StringComparison.Ordinal));
        var triggerIndex = Array.FindIndex(resultEvents, gameEvent =>
            string.Equals(gameEvent.Kind, "BATTLEFIELD_TRIGGER_RESOLVED", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["trigger"] as string, TriggerKinds.BattlefieldHeldDrawOne, StringComparison.Ordinal));
        Assert.True(heldIndex >= 0);
        Assert.True(triggerIndex > heldIndex);

        var triggerEvent = resultEvents[triggerIndex];
        Assert.Equal("P2", triggerEvent.Payload["playerId"]);
        Assert.Equal(battlefieldObjectId, triggerEvent.Payload["battlefieldObjectId"]);
        Assert.Equal(HiddenValleyBattlefieldHeldDrawCardNo, triggerEvent.Payload["battlefieldCardNo"]);
        Assert.Equal(attackerObjectId, triggerEvent.Payload["sourceObjectId"]);
        Assert.Equal(1, triggerEvent.Payload["drawCount"]);

        Assert.Contains(result.Events, gameEvent =>
            string.Equals(gameEvent.Kind, "CARD_DRAWN", StringComparison.Ordinal)
            && string.Equals(gameEvent.Payload["playerId"] as string, "P2", StringComparison.Ordinal)
            && Equals(1, gameEvent.Payload["count"]));

        Assert.Contains(expectedDrawnObjectId, result.State.PlayerZones["P2"].Hand);
        Assert.DoesNotContain(expectedDrawnObjectId, result.State.PlayerZones["P2"].MainDeck);
        Assert.Contains(defenderObjectId, result.State.PlayerZones["P2"].Battlefields);
        Assert.Equal(battlefieldObjectId, result.State.ObjectLocations[defenderObjectId].BattlefieldObjectId);
        AssertNoHiddenZoneLeak(result);
    }

