    private static async ValueTask<ResolutionResult> SubmitBattlefieldFriendlySpellDrawSpellAsync(
        MatchSession session,
        ResolutionResult current,
        string playerId,
        string intentId)
    {
        Assert.Equal(playerId, current.State.ActivePlayerId);
