    private static MatchState BuildBattlefieldHeldSevenUnitsWinMidgameInitialState(MatchState state)
    {
        var midgameState = BuildSpecificCardsForPlayersMidgameInitialState(
            state,
            new Dictionary<string, (IReadOnlyList<string> CardNos, RunePool RunePool)>(StringComparer.Ordinal)
            {
                ["P1"] = (
                    [WatchfulSentinelCardNo],
                    new RunePool(mana: 6, power: 0, new Dictionary<string, int>(StringComparer.Ordinal))),
                ["P2"] = (
                    [WildclawBeastmasterCardNo],
                    new RunePool(mana: 6, power: 0, new Dictionary<string, int>(StringComparer.Ordinal)))
            });
        var battlefieldId = BattlefieldObjectIdForCardNo(
            midgameState,
            "P2",
            GrandPlazaBattlefieldHeldSevenUnitsWinCardNo);
        var attackerObjectId = FindHandCardObjectByCardNo(
            midgameState,
            "P1",
            WatchfulSentinelCardNo)
            ?? throw new InvalidOperationException("B0 Grand Plaza setup could not find Watchful Sentinel in P1 hand.");
        var defenderObjectId = FindHandCardObjectByCardNo(
            midgameState,
            "P2",
            WildclawBeastmasterCardNo)
            ?? throw new InvalidOperationException("B0 Grand Plaza setup could not find Wildclaw Beastmaster in P2 hand.");
        var p2ZonesBefore = midgameState.PlayerZones["P2"];
        var extraDefenderObjectIds = p2ZonesBefore.Hand
            .Concat(p2ZonesBefore.MainDeck)
            .Concat(p2ZonesBefore.Base)
            .Where(objectId => !string.Equals(objectId, defenderObjectId, StringComparison.Ordinal))
            .Where(objectId => midgameState.CardObjects.TryGetValue(objectId, out var cardObject)
                && cardObject.Tags.Contains(CardObjectTags.UnitCard, StringComparer.Ordinal)
                && !ApplyRegisteredSourceUnitTags(cardObject).Contains(CardObjectTags.Standby, StringComparer.Ordinal))
            .Distinct(StringComparer.Ordinal)
            .Take(6)
            .ToArray();
        Assert.Equal(6, extraDefenderObjectIds.Length);
        var defenderUnitObjectIds = new[] { defenderObjectId }.Concat(extraDefenderObjectIds).ToArray();

        var playerZones = midgameState.PlayerZones.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        var p1Zones = playerZones["P1"];
        var p2Zones = playerZones["P2"];
        playerZones["P1"] = p1Zones with
        {
            Hand = p1Zones.Hand.Where(objectId => !string.Equals(objectId, attackerObjectId, StringComparison.Ordinal)).ToArray(),
            Battlefields = p1Zones.Battlefields.Concat([attackerObjectId]).ToArray()
        };
        playerZones["P2"] = p2Zones with
        {
            MainDeck = p2Zones.MainDeck.Where(objectId => !defenderUnitObjectIds.Contains(objectId, StringComparer.Ordinal)).ToArray(),
            Hand = p2Zones.Hand.Where(objectId => !defenderUnitObjectIds.Contains(objectId, StringComparer.Ordinal)).ToArray(),
            Base = p2Zones.Base.Where(objectId => !defenderUnitObjectIds.Contains(objectId, StringComparer.Ordinal)).ToArray(),
            Battlefields = p2Zones.Battlefields.Concat(defenderUnitObjectIds).ToArray()
        };

        var objectLocations = midgameState.ObjectLocations.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        objectLocations[attackerObjectId] = new ObjectLocationState("P1", "BATTLEFIELD", battlefieldId);
        foreach (var defenderUnitObjectId in defenderUnitObjectIds)
        {
            objectLocations[defenderUnitObjectId] = new ObjectLocationState("P2", "BATTLEFIELD", battlefieldId);
        }

        var cardObjects = midgameState.CardObjects.ToDictionary(entry => entry.Key, entry => entry.Value, StringComparer.Ordinal);
        cardObjects[attackerObjectId] = cardObjects[attackerObjectId] with
        {
            Damage = 0,
            IsExhausted = false,
            IsFaceDown = false,
            IsAttacking = false,
            IsDefending = false,
            Tags = ApplyRegisteredSourceUnitTags(cardObjects[attackerObjectId]),
            OwnerId = "P1",
            ControllerId = "P1"
        };
        foreach (var defenderUnitObjectId in defenderUnitObjectIds)
        {
            cardObjects[defenderUnitObjectId] = cardObjects[defenderUnitObjectId] with
            {
                Damage = 0,
                IsExhausted = false,
                IsFaceDown = false,
                IsAttacking = false,
                IsDefending = false,
                Tags = ApplyRegisteredSourceUnitTags(cardObjects[defenderUnitObjectId]),
                OwnerId = "P2",
                ControllerId = "P2"
            };
        }

        return midgameState with
        {
            ActivePlayerId = "P1",
            TurnPlayerId = "P1",
            PlayerZones = playerZones,
            ObjectLocations = objectLocations,
            CardObjects = cardObjects,
            UntilEndOfTurnEffects = midgameState.UntilEndOfTurnEffects
                .Where(effectId => !string.Equals(
                    effectId,
                    BattlefieldTaskMarkers.BattleSkipped(battlefieldId),
                    StringComparison.Ordinal))
                .Concat([BattlefieldTaskMarkers.SpellDuelCompleted(battlefieldId)])
                .Distinct(StringComparer.Ordinal)
                .ToArray()
        };
    }

